package com.wizzadrds.theworldremembers.voice; public record VoiceStateDelivery(float rate,float pitch,float expressiveness){public static VoiceStateDelivery from(VoiceProfile p,VoiceState s){float r=p.rate(),pi=p.pitch(),e=p.expressiveness();switch(s){case TIMID->e*=.65f;case NERVOUS->{r*=1.12f;pi*=1.05f;}case TIRED->{r*=.82f;pi*=.94f;}case ANGRY->{r*=1.08f;pi*=.88f;e=Math.min(1,e*1.25f);}case EXCITED->{r*=1.15f;pi*=1.08f;e=Math.min(1,e*1.2f);}default->{}}return new VoiceStateDelivery(r,pi,e);}}